class Solution { public: string mostCommonWord(string paragraph,vector<string>& banned){unordered_set<string> blocked(banned.begin(),banned.end());unordered_map<string,int> frequency;string answer,word;int best=0;paragraph+=' ';for(char c:paragraph){if(isalpha(c))word+=tolower(c);else if(!word.empty()){if(!blocked.count(word)&&++frequency[word]>best){best=frequency[word];answer=word;}word.clear();}}return answer;} };
